<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import {refreshAll} from '$app/navigation';
 import type {AppData} from '#lib/client/types.ts';
 import {command,permitted} from '#lib/client/api.ts';
 import ReferencePicker from './ReferencePicker.svelte';
 import FreshPassword from './FreshPassword.svelte';
 import Status from './Status.svelte';
 let {data}:{data:AppData}=$props();
 let fenceKind=$state('write_stop'),statement=$state(''),watermark=$state(''),evidence=$state(''),batchId=$state(''),finalDelta=$state(false),fresh=$state(false),busy=$state(false),error=$state(''),notice=$state(''),releaseStatement=$state('');
 const kinds=[['customers','Kunden'],['suppliers','Lieferanten'],['products','Produkte'],['orders','Aufträge'],['invoices','Originalrechnungen'],['payments','Zahlungen'],['employees','Personalstämme'],['historical_documents','Dokumentzuordnungen']];
 let counts:Record<string,number>=$state(Object.fromEntries(kinds.map(([k])=>[k,0]))),currency=$state('EUR'),net=$state('0'),gross=$state('0'),incoming=$state('0'),outgoing=$state('0'),open=$state('0');
 const cut=$derived(data.detail!),batches=$derived(data.related?.cutover_batches??[]),finance=$derived(permitted(data,'finance'));
 async function run(name:string,payload:any){if(busy)return;busy=true;error='';notice='';try{await command(name,cut.id,payload,cut.version);notice='Der Datenschnitt wurde aktualisiert. Prüfen Sie den bestätigten Stand.';await refreshAll();}catch(e){error=e instanceof Error?e.message:'Der Schritt konnte nicht bestätigt werden.';}finally{busy=false;}}
 const decimal=(s:string)=>s.replace(',','.');
</script>
<section class="panel"><header class="panel-header"><div><h2>Datenwechsel sicher abschließen</h2><p class="small muted">Quellnachweis → finaler Deltaimport → Abschlussabgleich → neue Schreibstrecke</p></div><Status value={cut.status}/></header><div class="panel-body stack">
 <p>Die Originale und der vorgeschriebene Zugang zum Altarchiv bleiben bestehen. Während des finalen Datenschnitts sind neue Finanzbuchungen gesperrt.</p>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if notice}<div class="notice info" role="status">{notice}</div>{/if}
 {#if cut.status==='draft'&&finance}<form class="stack" onsubmit={(e)=>{e.preventDefault();run('migration.cutover.fence',{source_fence_kind:fenceKind,source_fence_statement:statement,...(watermark?{source_watermark:watermark}:{}),evidence_document_version_id:evidence,source_totals:{counts,currencies:{[currency]:{invoice_net:decimal(net),invoice_gross:decimal(gross),payment_incoming:decimal(incoming),payment_outgoing:decimal(outgoing),receivable_open:decimal(open)}}}});}}><h3>1. Tatsächlichen Quellschnitt bestätigen</h3><label for="cut-kind">Verfahren</label><select use:searchableSelect={fenceKind} id="cut-kind" bind:value={fenceKind}><option value="write_stop">Altsystem ist für neue Buchungen gesperrt</option><option value="watermark">Konsistenter Änderungs-Watermark mit lückenloser Übernahme</option></select><label for="cut-evidence">Geprüfter Nachweis</label><ReferencePicker id="cut-evidence" bind:value={evidence} reference="document-versions" required/>{#if fenceKind==='watermark'}<label for="cut-watermark">Watermark / letzte übernommene Änderung</label><input id="cut-watermark" bind:value={watermark} required minlength="3"/>{/if}<label for="cut-statement">Verantwortliche Person, Zeitpunkt und nachvollziehbares Vorgehen</label><textarea id="cut-statement" bind:value={statement} required minlength="20" rows="4"></textarea><h3>Erwarteter vollständiger Altbestand</h3><p class="field-help">Tragen Sie bestätigte Anzahlen und Summen aus dem Altsystem ein. Der Abschluss vergleicht diese mit allen zugeordneten Chargen einschließlich des finalen Deltas.</p><div class="fields">{#each kinds as [key,name]}<label>{name}<input type="number" min="0" step="1" bind:value={counts[key]} required/></label>{/each}<label>Währung<input bind:value={currency} pattern={'[A-Z]{3}'} maxlength="3" required/></label>{#each [{label:'Rechnungen netto',key:'net'},{label:'Rechnungen brutto',key:'gross'},{label:'Zahlungseingänge',key:'incoming'},{label:'Zahlungsausgänge',key:'outgoing'},{label:'Offene Forderungen',key:'open'}] as field}<label>{field.label}{#if field.key==='net'}<input bind:value={net} inputmode="decimal" required/>{:else if field.key==='gross'}<input bind:value={gross} inputmode="decimal" required/>{:else if field.key==='incoming'}<input bind:value={incoming} inputmode="decimal" required/>{:else if field.key==='outgoing'}<input bind:value={outgoing} inputmode="decimal" required/>{:else}<input bind:value={open} inputmode="decimal" required/>{/if}</label>{/each}</div><FreshPassword bind:confirmed={fresh}/><button class="btn primary" disabled={busy||!fresh||!evidence}>Quellschnitt bestätigen und neue Finanzbuchungen sperren</button></form>{/if}
 {#if ['draft','source_fenced'].includes(cut.status)}<form class="stack" onsubmit={(e)=>{e.preventDefault();run('migration.cutover.attach',{batch_ids:[batchId],is_final_delta:finalDelta});}}><h3>2. Geprüfte Importcharge zuordnen</h3><ReferencePicker id="cut-batch" bind:value={batchId} reference="imports" required/>{#if cut.status==='source_fenced'}<label class="confirm"><input type="checkbox" bind:checked={finalDelta}/>Diese Charge ist der nach dem bestätigten Quellschnitt angelegte finale Deltaimport.</label>{/if}<button class="btn" disabled={busy||!batchId}>Charge zuordnen</button></form>{/if}
 {#if batches.length}<div class="table-scroll"><table class="data-table"><thead><tr><th>Charge</th><th>Umfang</th><th>Stand</th></tr></thead><tbody>{#each batches as batch}<tr><td><a class="text-link" href={`/imports/${batch.id}`}>{batch.name}</a></td><td>{batch.is_final_delta?'Finales Delta':'Grundbestand'}</td><td><Status value={batch.status}/></td></tr>{/each}</tbody></table></div>{/if}
 {#if finance&&['source_fenced','reconciled'].includes(cut.status)}<button class="btn" disabled={busy} onclick={()=>run('migration.cutover.reconcile',{})}>3. Anzahlen und Beträge jetzt abgleichen</button>{/if}
 {#if cut.reconciliation}<div class:success={cut.reconciliation.matches} class="reconciliation"><h3>{cut.reconciliation.matches?'Alle Anzahlen und Beträge stimmen überein':'Abweichungen vor der Freigabe klären'}</h3><dl>{#each kinds as [key,name]}<div><dt>{name}</dt><dd>{cut.reconciliation.totals?.counts?.[key]??0} übernommen / {cut.reconciliation.expected?.counts?.[key]??0} erwartet</dd></div>{/each}</dl>{#each Object.entries(cut.reconciliation.totals?.currencies??{}) as [curr,totals]}<p><strong>{curr}</strong></p><dl>{#each Object.entries(totals as Record<string,string>) as [key,value]}<div><dt>{{invoice_net:'Rechnungen netto',invoice_gross:'Rechnungen brutto',payment_incoming:'Zahlungseingänge',payment_outgoing:'Zahlungsausgänge',receivable_open:'Offene Forderungen'}[key]??key}</dt><dd>{value} / erwartet {cut.reconciliation.expected?.currencies?.[curr]?.[key]??'nicht angegeben'}</dd></div>{/each}</dl>{/each}</div>{/if}
 {#if cut.status==='reconciled'&&finance}<form class="stack" onsubmit={(e)=>{e.preventDefault();run('migration.cutover.release',{statement:releaseStatement});}}><h3>4. Neue Schreibstrecke ausdrücklich freigeben</h3><label for="cut-release">Abschlussbestätigung und verantwortliche Person</label><textarea id="cut-release" bind:value={releaseStatement} minlength="30" rows="3" required></textarea><FreshPassword bind:confirmed={fresh}/><button class="btn primary" disabled={busy||!fresh}>Neue Schreibstrecke nach erneutem Abschlussabgleich freigeben</button></form>{/if}
 {#if cut.status==='released'}<div class="notice info">Der Datenschnitt ist abgeschlossen. Nummernkreise wurden mit den übernommenen Originalen verglichen; die neue Schreibstrecke ist freigegeben.</div>{/if}
</div></section>
<style>.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.fields label{display:grid;gap:8px}.confirm{display:flex;gap:12px;align-items:flex-start}.reconciliation{background:var(--wash);padding:20px;border:1px solid var(--line);border-radius:8px}dl>div{display:flex;justify-content:space-between;gap:16px;padding:8px 0}dd{text-align:right}input[type=checkbox]{width:20px;height:20px;min-height:20px}@media(max-width:650px){.fields{grid-template-columns:1fr}dl>div{display:block}dd{text-align:left}}</style>
